@import 'c/ihStyles';

.shell {
    position: relative;
}
.editor-head {
    justify-content: center;
}

/* ---------- layout: steps + side summary ---------- */
.layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(220px, 300px);
}
.main {
    min-width: 0;
    padding: 16px 20px;
    display: flex;
    flex-direction: column;
    gap: 14px;
}
.side {
    min-width: 0;
    padding: 16px 20px;
    background: #fafaf9;
    border-left: 1px solid var(--ih-line-2);
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.foot {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    padding: 12px 20px;
    background: #f7f7f7;
    border-top: 1px solid var(--ih-line);
    border-radius: 0 0 var(--ih-radius) var(--ih-radius);
}

/* ---------- stepper ---------- */
.stepper {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px;
    margin: 0;
    padding: 0;
    list-style: none;
}
.stepper-item {
    display: flex;
    align-items: center;
    gap: 6px;
    flex: 1 1 auto;
    min-width: 0;
}
.step {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: 0;
    background: none;
    padding: 4px;
    font: inherit;
    font-size: 14px;
    color: var(--ih-quiet);
    cursor: pointer;
    border-radius: 8px;
    white-space: nowrap;
}
.step:focus-visible {
    outline: 2px solid var(--ih-brand);
    outline-offset: 2px;
}
.step-dot {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
    width: 26px;
    height: 26px;
    border-radius: 50%;
    border: 2px solid #c9c9c9;
    font-weight: 700;
    font-size: 13px;
    background: var(--ih-surface);
}
.step_on {
    color: var(--ih-brand);
    font-weight: 700;
}
.step_on .step-dot {
    border-color: var(--ih-brand);
    box-shadow: 0 0 0 3px var(--ih-brand-soft);
}
.step_done .step-dot {
    border-color: var(--ih-brand);
    background: var(--ih-brand);
    color: #ffffff;
}
.step_bad .step-dot {
    border-color: var(--ih-bad);
    background: var(--ih-bad-bg);
    color: var(--ih-bad-ink);
}
.step-line {
    flex: 1 1 24px;
    min-width: 12px;
    height: 2px;
    background: var(--ih-line);
}
.step-line_done {
    background: var(--ih-brand);
}

/* ---------- fields ---------- */
.fields {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 14px 20px;
}
.fld {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
}
.fld_wide {
    grid-column: 1 / -1;
}
.hint {
    margin: 0;
    font-size: 12px;
    color: var(--ih-quiet);
    overflow-wrap: anywhere;
}
.hint:empty {
    display: none;
}
.hint_strong {
    color: var(--ih-ink-2);
    font-weight: 600;
}
.label-like {
    margin: 0;
    font-size: 12px;
    color: var(--ih-ink-2);
}
.linkish {
    border: 0;
    background: none;
    padding: 0 0 0 6px;
    font: inherit;
    color: var(--ih-brand);
    cursor: pointer;
    text-decoration: underline;
}
.path-state {
    display: inline-block;
    margin-left: 6px;
    padding: 1px 8px;
    border-radius: 6px;
}
.path-state_ok {
    background: var(--ih-ok-bg);
    color: var(--ih-ok-ink);
}
.path-state_bad {
    background: var(--ih-warn-bg);
    color: var(--ih-warn-ink);
}
.step-error p {
    margin: 0;
}

/* ---------- last step ---------- */
.checks {
    display: flex;
    flex-direction: column;
    gap: 8px;
    border-top: 1px solid var(--ih-line-2);
    padding-top: 12px;
}
.sub {
    margin: 0;
    font-size: 14px;
    font-weight: 700;
}
.problems {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.problem {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    width: 100%;
    padding: 8px 10px;
    border: 0;
    border-radius: 8px;
    font: inherit;
    font-size: 13px;
    text-align: left;
    cursor: pointer;
}
.problem_error {
    background: var(--ih-bad-bg);
    color: var(--ih-bad-ink);
}
.problem_warn {
    background: var(--ih-warn-bg);
    color: var(--ih-warn-ink);
}
.problem-text {
    flex: 1 1 auto;
    min-width: 0;
    overflow-wrap: anywhere;
}
.problem-step {
    flex: 0 0 auto;
    font-size: 12px;
    opacity: 0.8;
}
.check-result {
    align-items: center;
    flex-wrap: wrap;
}

/* ---------- key / value rows (summary and view cards) ---------- */
.kv {
    margin: 0;
    display: flex;
    flex-direction: column;
}
.kv-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 12px;
    padding: 7px 0;
    border-bottom: 1px solid var(--ih-line-2);
    font-size: 13px;
}
.kv-row dt {
    flex: 0 0 auto;
    max-width: 45%;
    color: var(--ih-quiet);
}
.kv-row dd {
    margin: 0;
    min-width: 0;
    text-align: right;
    overflow-wrap: anywhere;
}
.kv-mono dd {
    font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
    font-size: 12px;
}

/* ---------- view cards ---------- */
.cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 16px;
}
.sum-card {
    min-width: 0;
    border: 1px solid var(--ih-line);
    border-radius: 10px;
    padding: 14px 18px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}
.sum-title {
    display: flex;
    align-items: center;
    gap: 10px;
    margin: 0;
    font-size: 14px;
    font-weight: 700;
}
.num {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    border-radius: 50%;
    background: var(--ih-brand);
    color: #ffffff;
    font-size: 12px;
}
.more {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

/* ---------- narrow screens ---------- */
@media (max-width: 860px) {
    .layout {
        grid-template-columns: minmax(0, 1fr);
    }
    .side {
        border-left: 0;
        border-top: 1px solid var(--ih-line-2);
    }
}
@media (max-width: 520px) {
    .main,
    .side {
        padding: 12px;
    }
    .step-label {
        display: none;
    }
    .step_on .step-label {
        display: inline;
    }
    .fields,
    .cards {
        grid-template-columns: minmax(0, 1fr);
    }
    .kv-row {
        flex-direction: column;
        gap: 2px;
    }
    .kv-row dt {
        max-width: none;
    }
    .kv-row dd {
        text-align: left;
    }
}
